{
  "$schema": "https://raw.githubusercontent.com/mmdemirbas/html-doc/main/kit/schema/page.schema.json",
  "kind": "page",
  "schema_version": 1,
  "title": "My note",
  "accent": "teal",
  "meta": {
    "eyebrow": "Notes",
    "subtitle": "One-line subtitle below the H1.",
    "date": "2026-05-18",
    "order": 10,
    "summary": "One-line summary for nav tooltips and llms.txt."
  },
  "blocks": [
    { "kind": "tldr", "summary": "...", "bullets": ["..."] },
    { "kind": "section", "id": "overview", "title": "Overview", "blocks": [
      { "kind": "paragraph", "content": "Plain prose works as a string." }
    ]}
  ]
}

code.source:
{ "kind": "list", "style": "bullet", "items": [
  "Plain string item.",
  ["Or an array with ", { "kind": "code", "text": "inline" }, " nodes."]
] }

{
  "kind": "annotated-code",
  "language": "javascript",
  "source": "const x = 1; // (1)\nfunction greet(name) {\n  return `Hello, ${name}!`;\n}",
  "annotations": [
    { "id": 1, "content": "<code>const</code> creates a block-scoped binding." },
    { "id": 2, "content": "Function body — highlights lines 2-4.", "lines": "2-4" },
    { "id": 3, "content": "Template-literal interpolation.", "match": "${name}" }
  ]
}

{
  "kind": "callout",
  "type": "warn",
  "title": "Watch the lock",
  "content": "Compaction holds a metadata lock; long jobs block writers."
}

{
  "kind": "info-tip",
  "summary": "How the lock actually works",
  "content": [
    { "kind": "paragraph", "content": "Two writers race ..." }
  ]
}

{
  "kind": "tldr",
  "summary": "One-sentence essence.",
  "bullets": [
    "Three to five concrete points.",
    "Each bullet may include inline kinds like glossary terms."
  ]
}
